void Main() {
    var x = 10;
    Print(x += (x = 3)); Print(x);
    Print(x *= x++); Print(x);
    Print(x -= ++x); Print(x);
    x = 20; Print(x /= (x = 4)); Print(x);
    x = 20; Print(x %= (x = 6)); Print(x);
    var a = 1; var b = 2;
    Print(a += b *= 3); Print(a); Print(b);
    long wide = 1; wide += 12; Print(wide);
    var text = "A"; Print(text += (text = "B")); Print(text);
    text += 5; Print(text);
    var min = -2147483648; min %= -1; Print(min);
    x = 2147483647; x += 1; Print(x);
}
